  tH = `Похоже, права вашего аккаунта ограничены. Чтобы предотвратить злоупотребления, мы разрешаем номинировать игры только пользователям, совершившим покупки в Steam на 5 долларов США. %1$s, чтобы узнать больше.`,
  nH = `Похоже, права вашего аккаунта ограничены. Чтобы предотвратить злоупотребления, мы разрешаем голосовать только пользователям, совершившим покупки в Steam на 5 долларов США. %1$s, чтобы узнать больше.`,
