  OH = `Самый инновационный геймплей`,
  kH = `Лучшая игра, которая вам не даётся`,
  AH = `Лучший саундтрек`,
  jH = `Лучшая игра с выдающимся сюжетом`,
  MH = `Устройтесь поудобнее`,
  NH = `Лучшая игра на ходу`,
  PH = `Может, дело в увлекательном геймплее или в цепляющей истории. А может, дело в добротных персонажах, безукоризненном дизайне или в затягивающей сетевой игре. Какой бы ни была причина, победитель в номинации «Игра года» мгновенно становится классикой.`,
  FH = `Эта игра не просто маскирует виртуальную реальность под обычную. Она улучшает реальность, используя преимущества виртуальной среды, и расширяет границы виртуального измерения.`,
  IH = `Эта игра — уже не новинка. Далеко позади осталось то время, когда разработчики впервые явили миру своё творение. Как настоящие любящие родители, они не прекращают растить и поддерживать своё дитя. И по сей день в игру добавляется что-то новенькое.`,
  LH = `Есть такие игры, которые не раскроются полностью, если играть в них одному. Может, будет веселее, если вашу спину будет прикрывать друг? Или подставит свою спину под ваш нож — это уж кому как нравится. Так или иначе, если вы собираетесь с друзьями, в этой игре вас ждёт веселье.`,
  RH = `Визуальный стиль не должен стремиться к полной реалистичности и достоверности (хотя сама по себе это благородная цель)... Он описывает уникальный внешний вид и мироощущение.`,
  zH = `Создатели этой игры стоят на передовой творческих экспериментов, свежих перспектив и мозгодробительных сюрпризов. Эта игра восхищала, вдохновляла и развлекала не испытанной ранее новизной.`,
  BH = `Это игра не для слабонервных, она вознаграждает упорство. Она самая сложная из тех, что нам полюбились.`,
  VH = `Этот невоспетый герой заслуживает признания за выдающееся музыкальное сопровождение. Сей саундтрек — само совершенство! `,
  HH = `Иногда просто хочется погрузиться в сюжет с головой, и эта игра производит неизгладимое впечатление. Она захватывает, как любая мыльная опера, и выверена, будто первоклассное ТВ-шоу. Брависсимо! Аплодируем игре, затронувшей душу!`,
  UH = `Эта игра — противоядие от напряжения. Она спокойная, она расслабляющая, она погрузит вас в дзен, а ваши заботы исчезнут без следа.`,
  WH = `Эта игра была так хороша, что её хотелось брать с собой... что вы и делали! И, к счастью, её бесконечная играбельность лишь увеличилась на ходу.`,
  GH = `Только VR`,
  KH = `Поддержка VR`,
  qH = `До следующего случайного розыгрыша: %1$s!`,
  JH = `Время до следующего случайного розыгрыша.`,
  YH = `Смотрите трансляцию для участия в розыгрыше!`,
  XH = `Проводится случайный розыгрыш`,
  ZH = `Число счастливых победителей на данный момент!`,
  QH = `Раздача завершена. Спасибо за участие.`,
  $H = `Раздача завершена, счастливых победителей: %1$s. Спасибо за участие.`,
